begin;
set search_path=public,extensions;
select no_plan();
insert into public.conversations(id,job_id,worker_id) values('a0700000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002');
insert into public.conversation_members(conversation_id,user_id) values('a0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001'),('a0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002');
select throws_ok($$insert into public.conversation_members(conversation_id,user_id) values('a0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003')$$,'P0001',null,'only actual job parties can join');
select throws_ok($$insert into public.messages(conversation_id,sender_id,body) values('a0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','Unrelated message')$$,'P0001',null,'unrelated sender rejected');
insert into public.messages(id,conversation_id,sender_id,body,sequence) values('b0700000-0000-0000-0000-000000000001','a0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','Synthetic message',999);
select is((select sequence::int from public.messages where id='b0700000-0000-0000-0000-000000000001'),1,'server assigns sequence regardless of supplied value');
select throws_ok($$update public.messages set body='Altered history' where id='b0700000-0000-0000-0000-000000000001'$$,'P0001',null,'sent body immutable');
select lives_ok($$update public.messages set deleted_at=now() where id='b0700000-0000-0000-0000-000000000001'$$,'moderation can tombstone');
select throws_ok($$update public.messages set deleted_at=null where id='b0700000-0000-0000-0000-000000000001'$$,'P0001',null,'tombstone cannot be undone');
update public.bookings set status='confirmed' where id='80000000-0000-0000-0000-000000000001';
select throws_ok($$update public.bookings set scheduled_start=now()+interval '1 day',scheduled_end=now()+interval '1 day 1 hour' where id='80000000-0000-0000-0000-000000000001'$$,'P0001',null,'unagreed appointment change rejected');
insert into private.booking_reschedules(id,booking_id,proposed_by,base_version,starts_at,ends_at,expires_at) values('c0700000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',1,now()+interval '1 day',now()+interval '1 day 1 hour',now()+interval '1 hour');
select throws_ok($$update private.booking_reschedules set status='accepted',decided_by=proposed_by,decided_at=now(),applied_version=2 where id='c0700000-0000-0000-0000-000000000001'$$,'P0001',null,'proposer cannot self accept');
update private.booking_reschedules set status='accepted',decided_by='10000000-0000-0000-0000-000000000002',decided_at=now(),applied_version=2 where id='c0700000-0000-0000-0000-000000000001';
select lives_ok($$update public.bookings set scheduled_start=now()+interval '1 day',scheduled_end=now()+interval '1 day 1 hour',version=2 where id='80000000-0000-0000-0000-000000000001'$$,'explicit other-party acceptance permits new window');
select throws_ok($$update private.booking_reschedules set ends_at=ends_at+interval '1 hour' where id='c0700000-0000-0000-0000-000000000001'$$,'P0001',null,'accepted terms immutable');
select throws_ok($$update public.bookings set final_total_cents=1 where id='80000000-0000-0000-0000-000000000001'$$,'P0001',null,'original quote price stays immutable');
insert into public.change_orders(id,booking_id,requested_by,scope_change,delta_cents,base_version,expires_at) values('d0700000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','Synthetic scope adjustment',500,2,now()+interval '1 hour');
select throws_ok($$update public.change_orders set status='accepted',decided_by=requested_by,decided_at=now(),applied_version=3 where id='d0700000-0000-0000-0000-000000000001'$$,'P0001',null,'scope cannot be self accepted');
update public.change_orders set status='accepted',decided_by='10000000-0000-0000-0000-000000000001',decided_at=now(),applied_version=3 where id='d0700000-0000-0000-0000-000000000001';
select is((select b.final_total_cents+sum(c.delta_cents) from public.bookings b join public.change_orders c on c.booking_id=b.id and c.status='accepted' where b.id='80000000-0000-0000-0000-000000000001' group by b.id),10500::numeric,'accepted changes derive total without rewriting original');
set constraints adjusted_work_total immediate;
select throws_ok($$insert into public.change_orders(booking_id,requested_by,scope_change,delta_cents,status,decided_by,decided_at,applied_version) values('80000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','Synthetic invalid adjustment',100000000,'accepted','10000000-0000-0000-0000-000000000001',now(),4)$$,'P0001',null,'database rejects effective price overflow');
select throws_ok($$insert into private.completion_submissions(booking_id,round,submitted_by,summary,review_due_at) values('80000000-0000-0000-0000-000000000001',1,'10000000-0000-0000-0000-000000000002','Synthetic completed work record',now()+interval '1 hour')$$,'P0001',null,'unstarted work cannot be completed');
update public.bookings set status='in_progress' where id='80000000-0000-0000-0000-000000000001';
select throws_ok($$insert into private.completion_submissions(booking_id,round,submitted_by,summary,review_due_at) values('80000000-0000-0000-0000-000000000001',1,'10000000-0000-0000-0000-000000000003','Synthetic completed work record',now()+interval '1 hour')$$,'P0001',null,'unrelated worker cannot submit proof');
insert into private.completion_submissions(id,booking_id,round,submitted_by,summary,review_due_at) values('e0700000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001',1,'10000000-0000-0000-0000-000000000002','Synthetic completed work record',now()+interval '1 hour');
select throws_ok($$update private.completion_submissions set status='confirmed',responded_by=submitted_by,responded_at=now() where id='e0700000-0000-0000-0000-000000000001'$$,'P0001',null,'worker cannot confirm own completion');
select throws_ok($$update private.completion_submissions set review_due_at=review_due_at+interval '1 hour' where id='e0700000-0000-0000-0000-000000000001'$$,'P0001',null,'review reminder cannot be silently extended');
insert into private.collaboration_assets(id,owner_id,job_id,conversation_id,purpose,storage_path,sha256,byte_size,state,retain_until) values('f0700000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','a0700000-0000-0000-0000-000000000001','message','synthetic/m07.jpg',repeat('a',64),100,'stored',now()+interval '1 hour');
select throws_ok($$insert into private.message_assets(message_id,asset_id) values('b0700000-0000-0000-0000-000000000001','f0700000-0000-0000-0000-000000000001')$$,'P0001',null,'message cannot attach somebody else’s upload');
select is((select public from storage.buckets where id='chat-attachments'),false,'chat bucket stays private');
select is((select count(*)::int from pg_policies where schemaname='storage' and policyname='collaboration_storage_server_only' and permissive='RESTRICTIVE'),1,'browser Storage bypass denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.messages),0,'actual member must use current server projection');
select is((select count(*)::int from public.change_orders),0,'proposal history cannot bypass current authorization');
select throws_ok('select * from private.completion_submissions','42501',null,'completion proof is private');
select throws_ok('select * from private.workflow_access_grants','42501',null,'audit access requires MFA server command');
reset role;
select * from finish();
rollback;
